using NexaConnect.Services.Kitchen.Application;using NexaConnect.Services.Kitchen.Domain;using NexaConnect.Services.Kitchen.Infrastructure;
namespace NexaConnect.UnitTests;
public sealed class KitchenTicketLifecycleTests
{
 [Fact]public async Task Lifecycle_enforces_order_and_idempotent_replay(){var store=new InMemoryKitchenTicketStore();Guid organization=Guid.NewGuid();var command=new CreateKitchenTicket(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),[new(Guid.NewGuid(),"Burger",1,"grill")]);var context=new KitchenMutationContext("operator",Guid.NewGuid());KitchenTicket first=await store.CreateAsync(organization,command,context,default);KitchenTicket replay=await store.CreateAsync(organization,command,context,default);Assert.Equal(first.TicketId,replay.TicketId);KitchenTicket started=await store.TransitionAsync(organization,first.TicketId,new(KitchenTicketStatus.InProgress,1),context,default);KitchenTicket transitionReplay=await store.TransitionAsync(organization,first.TicketId,new(KitchenTicketStatus.InProgress,2),context,default);Assert.Equal(started.ConcurrencyVersion,transitionReplay.ConcurrencyVersion);KitchenTicket ready=await store.TransitionAsync(organization,first.TicketId,new(KitchenTicketStatus.Ready,2),context,default);KitchenTicket completed=await store.TransitionAsync(organization,first.TicketId,new(KitchenTicketStatus.Completed,3),context,default);Assert.Equal(4,completed.ConcurrencyVersion);await Assert.ThrowsAsync<KitchenConflictException>(()=>store.TransitionAsync(organization,first.TicketId,new(KitchenTicketStatus.Cancelled,4),context,default));}
 [Fact]public async Task Conflicting_snapshot_and_stale_version_are_rejected(){var store=new InMemoryKitchenTicketStore();Guid organization=Guid.NewGuid();var command=new CreateKitchenTicket(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),[new(Guid.NewGuid(),"Burger",1,"grill")]);var context=new KitchenMutationContext("operator",Guid.NewGuid());KitchenTicket ticket=await store.CreateAsync(organization,command,context,default);await Assert.ThrowsAsync<KitchenConflictException>(()=>store.CreateAsync(organization,command with{Lines=[command.Lines.Single() with{Quantity=2}]},context,default));await Assert.ThrowsAsync<KitchenConflictException>(()=>store.TransitionAsync(organization,ticket.TicketId,new(KitchenTicketStatus.InProgress,2),context,default));}
}
